import { describe, it, expect } from 'vitest';
import { calculateSHGExpressions, type TensorType, type TensorTimeReversal } from './tensorProjection';

interface Pin {
  g: string;
  tt: TensorType;
  tr: TensorTimeReversal;
  setting: number;
  display: 'EX_EY' | 'E0_THETA';
  angles: [number, number, number, number, number, number];
  induced: string[];
  source: string[];
  raw: string;
}

function flattenRaw(source: { component: string; rawPoly?: Map<string, Map<string, number>> }[]): [string, number][] {
  const rows: [string, number][] = [];
  for (const s of source) {
    if (!s.rawPoly) continue;
    for (const chi of [...s.rawPoly.keys()].sort())
      for (const pair of [...s.rawPoly.get(chi)!.keys()].sort())
        rows.push([`${s.component}:${chi}:${pair}`, s.rawPoly.get(chi)!.get(pair)!]);
  }
  return rows;
}

